INSERT INTO `mission_eggs` (`callsign`, `egg`) VALUES
('airmessy', 'Try not to treat them all like they might be English =)'),
('alliance', 'Tip: Refer to FBs as \"fuel bases\" just to confuse everyone.'),
('aomercy', 'Tip: Players might not have brigade loyalty, but they\'ll follow bewbies anywhere...'),
('bable', 'Servers coming down in 5 minutes.'),
('badger', 'badger, badger, badger, badger, badger, badger, mission, leader!'),
('bigley', 'Retreat with care - pulling out too soon can create new, unforeseen headaches!'),
('bilton', 'Tip: Watch out for the snipers.'),
('bjackel', 'Tip: Warn them when iam3 is driving!'),
('blangeas', 'Tip: Pics of blangett might earn their obedience if nothing else does!'),
('blangett', 'Equipping new weapon: Bullwhip. Equipping new uniform: Leather catsuit.'),
('bloo', 'and just what do you think you\'re doing?'),
('bushman', 'Tip: 12-gauge to the head is not a facial.'),
('chkicker', 'Kill A Rat does not automatically mean spawn a bomber, jerk.'),
('company0', 'Tip: There is more to the game other than drama in forums. <3'),
('csm308', 'Alan, alan, alan, alan. That\'s not his name. Steve, steve, steve.'),
('czstigur', 'Damned CRS... Or are they?'),
('dale', 'Orders posted in Swedish may confuse and scare - avoid unless all members are from Uppsala!'),
('dover', 'Sexy ammo is fine, but wash your hands before loading it...'),
('gdg', '\'gdg\'? That stand for \'god damn girls\'? Something you didn\'t tell the army recruiter??? :)'),
('gibbo', 'I know you\'ll never read this so I might as well say something insulting... :)'),
('gophur', 'shouldn\'t you be doing something else?'),
('heinzg', 'You can\'t beat a good Papa Johns. Thank you, from all the Rats :)'),
('iam3', 'TIP: QUICK, FETCH DADDY!!!!!!!!!'),
('ibe37', '37 that was 13 years ago!!!!'),
('icetwp', 'Tip: Politeness gets you places'),
('inchfan', 'Remember: Chicks Dig Cappers!'),
('katona', 'Mistress Katona leads from the front!'),
('kc25', 'Pizza makes for happy rats! Thanks KC25!'),
('kms', 'Camel Toe: For fat chicks, refer to it as, \"Moose Knuckle.\"'),
('knotking', 'How\'s that Submarine in Canada, eh?'),
('krieger', 'Gimmie 2 Utah, gimmie 2!'),
('liluh', 'Genetically engineered to be under $10 at your local market!'),
('lince', 'You owe Xoom a pizza, Lin-chay'),
('lindir', 'Tip: When translating, remember that \"Rafter\" is a very rude word in English...'),
('lordjim', 'Offering yourself up to be a sex slave on side chat is not permitted.'),
('magnumus', 'What what, what, what, what what'),
('melody', 'Remember: Sugar gliders are not standard mission-leader issue.'),
('moxin', 'ERROR: Setting post count to zero.'),
('ny75', 'IT\'s Homeless Season!!!!'),
('ohm', 'Cool, so... ANYWAYS.... No Diabeto'),
('oldzeke', 'Precisely how old is old?'),
('potthead', 'If smoke gets in your eyes, lift head out of ashtray.'),
('quizno', 'WOOF! Show them who\'s boss!'),
('rebel357', 'With a Rebel Yell He Screams MORE MORE MORE !'),
('rooke', 'Tip: Don\'t try and get in the back of Gibbo quite so literally in future...'),
('scum', 'Tip: Tell them it\'s your name, not an insult...'),
('shifty', 'But still no medallion.'),
('slayer', 'You\'re the mission leader? Pack your bags, we\'re fooked.'),
('slob', 'Leaning is for woosies.'),
('socket', 'Aircraft can land at airfields too.'),
('sres', 'Clean rifle after humping it.'),
('vondoosh', 'Putting the Doosh in VonDoosh.'),
('xoom', 'What ...... I am in game ????  I should be making Chili'),
('zach ', 'It\'s Party Zach!!!');
