r\n\"Reims\",\r\n\"Rethel\",\r\n\"Revin\",\r\n\"Rocroi\",\r\n\"Roisel\",\r\n\"Ronse\",\r\n\"Roubaix\",\r\n\"Roye\",\r\n\"Rozoy\",\r\n\"Sains-Richaumont\",\r\n\"Sambreville\",\r\n\"Samer\",\r\n\"Saulty\",\r\n\"Sechault\",\r\n\"Seclin\",\r\n\"Sedan\",\r\n\"Sierck-les-Bains\",\r\n\"Signy\",\r\n\"Sissonne\",\r\n\"Solesmes\",\r\n\"Sommepy\",\r\n\"Somzee\",\r\n\"Spincourt\",\r\n\"St.Avold\",\r\n\"St.Omer\",\r\n\"St.Pol\",\r\n\"St.Quentin\",\r\n\"Ste.Menehould\",\r\n\"Stenay\",\r\n\"Suippes\",\r\n\"Thiaucourt\",\r\n\"Thionville\",\r\n\"Thulin\",\r\n\"Tournai\",\r\n\"Trelon\",\r\n\"Val-de-Vesle\",\r\n\"Valenciennes\",\r\n\"Veere\",\r\n\"Verdun\",\r\n\"Vervins\",\r\n\"Vireaux\",\r\n\"Vitry-En-Artois\",\r\n\"Vlissingen\",\r\n\"Vouziers\",\r\n\"Walcourt\",\r\n\"Warmeriville\",\r\n\"Watten\",\r\n\"Westkapelle\",\r\n\"Wissant\",\r\n\"Zottegem\",\r\n          },\r\n	 china = {\r\n	 },\r\n	},\r\n\r\n	-- Brigade deployments\r\n	-- { \"shortname\", \"cp name\" }\r\n	-- Special case: cp name can be \"offmap\"\r\n	brigades = \"offmap\"\r\n}\r\n\r\n\r\n', '2009-02-23 19:16:39'),
('brigade-elimination-int', 'intermission = {\r\n	title = \"Brigade Elimination\",\r\n\r\n	-- CP Ownerships\r\n	-- By default all CPs are reset to their original ownership,\r\n	-- to change this behavior specify one of:\r\n	--  default = \"none\" -- leaves the map alone\r\n	--  default = WWII_ENGLAND|WWII_FRANCE|WWII_GERMANY|WWII_CHINA\r\n	ownerships = {\r\n	 default = \"none\",\r\n	 uk = {\r\n	 },\r\n	 france = {\r\n	 },\r\n	 germany = {\r\n	 },\r\n	 china = {\r\n	 },\r\n	},\r\n\r\n	-- Brigade deployments\r\n	-- { \"shortname\", \"cp name\" }\r\n	-- Special case: cp name can be \"offmap\"\r\n	brigades = {\r\n	}\r\n}\r\n---- Enable the \"INTEL\" system telling players where to fight?\r\n---- Recommended: false (for campaigns)\r\newsCheckEnabled = true\r\n\r\n---- Interval between EWS checks\r\n---- Recommended: timeInSeconds({ minutes = 15 })\r\newsCheckInterval = timeInSeconds({ minutes = 10 })\r\n\r\n-- Automatic attack objective controls\r\n\r\ngameAOMinimumRatio = 0.6\r\n\r\n----------------------------------------------------------------------\r\n-- maxCaptureObjectives()\r\n--	Return the current maximum allowed capture objectives\r\n----------------------------------------------------------------------\r\n\r\nfunction maxCaptureObjectives (population)\r\n	-- If population is not specified, use the current chat population\r\n	if population == nil then population = getPopulation() end\r\n\r\n	local minimum, maximum = 3, 20\r\n	local populationPer = 55\r\n	local target = math.floor(population / populationPer)\r\n\r\n	if target > maximum then return maximum end\r\n	if target < minimum then return minimum end\r\n\r\n	-- Otherwise what we have is good\r\n	return target\r\nend\r\n\r\nunitReformTime_s = timeInSeconds({days = 10})\r\n\r\n', '2007-10-10 17:01:09'),
('default-intermission-setup', '-- commented out special brigade assignments.  bloo\r\n\r\n-- The \"intermission\" entity describes the parameters of this\r\n-- intermission. When the strat host \"runs\" the intermission,\r\n-- it will read this structure looking for various elements\r\n-- with specific names.\r\n\r\n-- Entities enclosed in bracket/apostrophes [\'\'] are field names.\r\n-- Entities in quotes \"\" are text\r\n-- Entities not in quotes, such as ENGLAND, are special values.\r\n\r\nintermission = {\r\n\r\n  ------------------------------\r\n  -- -- Intermission description\r\n\r\n  -- Give your intermission a name; this will be broadcast\r\n  -- as a system message on startup.\r\n\r\n  [\'title\'] = \"Default Intermission\" ,\r\n\r\n  -- We can prevent brigade movements for a finite period of time\r\n  [\'brigadeInitialMovementTime\'] = { days = 0, hours = 0, minutes = 0, seconds = 0 } ,\r\n\r\n  -------------------\r\n  -- -- CP Ownerships\r\n\r\n  -- By default all CPs are reset to their map start ownership,\r\n  -- to change this behavior specify one of:\r\n\r\n    --  [\'default\'] = \"none\" -- leaves the map alone\r\n    -- or\r\n    --  [\'default\'] = ENGLAND     (or FRANCE or GERMANY or CHINA)\r\n\r\n  -- You can also assign specific towns to specific countries, to do\r\n  -- this create a list for that country, where the country is\r\n  -- \"uk\", \"france\", \"germany\", \"neutralfriendly\" or \"neutralhostile\"\r\n  -- e.g.\r\n  --  [\'uk\'] = { \"Antwerp\", \"Bergen Op Zoom\" } ,\r\n\r\n  [\'ownerships\'] = {\r\n\r\n    -- \"none\" in quotes, ENGLAND, FRANCE, GERMANY or CHINA without quotes.\r\n    [\'default\'] = \"none\" , \r\n\r\n    [\'uk\'] = { \"Town1\", \"Town2\", \"Town3\" } ,\r\n    [\'france\'] = { },\r\n    [\'germany\'] = { \"TownX\", \"TownY\", \"TownZ\" } ,\r\n\r\n    -- Towns with the country of CHINA are neutral+friendly:\r\n     --  - PERMITS: factory supply\r\n     --  - DISABLES: bde move, attack, capture, damage, spawn\r\n\r\n    [\'neutralfriendly\'] = { \"SomeTown\", \"SomeOtherTown\" } ,\r\n\r\n    -- Towns with country=RUSSIA are neutral+hostile:\r\n     --  - PERMITS: attack, capture, damage\r\n     --  - DISABLES: bde move, spawn, factory supply\r\n\r\n    [\'neutralhostile\'] = { \"AnotherTown\", \"AnotherOtherTown\" } ,\r\n  },\r\n\r\n  ------------------------------\r\n  -- Brigade deployments\r\n  -- Example: { \"shortname\", \"cp name\" },\r\n  -- Special case: cp name can be \"offmap\"\r\n  -- Remember to put a comma after the }s\r\n\r\n  [\'brigades\'] = {\r\n--   { \"sas\", \"Antwerp\" } ,      -- Note comma at end!\r\n--   { \"1pdkg1\", \"Luxembourg\" } ,\r\n  }\r\n}\r\n\r\n---- You can override code from stratlib.lua etc here.\r\n\r\n\r\n', '2014-01-12 01:42:39');
