('DefaultDivisionalStart-INT', '--------------------------------------------------------------------------------\r\n-- DefaultDivisionalStart.lua\r\n-- Generated 9/27/2011 5:16:59 PM by docdoom using BECD v1.3.0.0\r\n--------------------------------------------------------------------------------\r\n-- Based on DefaultDivisionalStart.bemap\r\n--   Title:       Default Divisional Start\r\n--   Created:     9/27/2011 5:05:51 PM\r\n--   Modified:    9/27/2011 5:14:56 PM\r\n--   Description: Places all brigades inside their divisions for intermission\r\n--                non events\r\n--------------------------------------------------------------------------------\r\n\r\n-- NOTE: this file should be called from a wrapper script, see example in BECD installation folder\r\n\r\n\r\nbecd.start_file( \"DefaultDivisionalStart.bemap\", \"Default Divisional Start\" )\r\n\r\nbecd.start_cps()\r\nbecd.set_cp( \"Chichester\", 1, \"UK\", 1 )  -- Chichester owned British\r\nbecd.set_cp( \"Gosport\", 2, \"UK\", 1 )  -- Gosport owned British\r\nbecd.set_cp( \"British Training\", 4, \"UK\", 1 )  -- British Training owned British\r\nbecd.set_cp( \"French Training\", 6, \"FR\", 3 )  -- French Training owned French\r\nbecd.set_cp( \"German Training\", 21, \"DE\", 4 )  -- German Training owned German\r\nbecd.set_cp( \"Mendig\", 23, \"DE\", 4 )  -- Mendig owned German\r\nbecd.set_cp( \"Hahn\", 24, \"DE\", 4 )  -- Hahn owned German\r\nbecd.set_cp( \"Oplade\", 25, \"DE\", 4 )  -- Oplade owned German\r\nbecd.set_cp( \"Langenfeld\", 26, \"DE\", 4 )  -- Langenfeld owned German\r\nbecd.set_cp( \"Koln\", 28, \"DE\", 4 )  -- Koln owned German\r\nbecd.set_cp( \"Dusseldorf\", 32, \"DE\", 4 )  -- Dusseldorf owned German\r\nbecd.set_cp( \"Ratingen\", 36, \"DE\", 4 )  -- Ratingen owned German\r\nbecd.set_cp( \"Dormagen\", 39, \"DE\", 4 )  -- Dormagen owned German\r\nbecd.set_cp( \"Neuss\", 41, \"DE\", 4 )  -- Neuss owned German\r\nbecd.set_cp( \"Bruhl\", 42, \"DE\", 4 )  -- Bruhl owned German\r\nbecd.set