INSERT INTO `strat_scripts` (`name`, `code`, `modified`) VALUES
('deployments-baseline', '----==== REFERENCE ONLY - THIS IS THE BASELINE RARESPAWN DEPLOYMENT LIST ====----\r\n----==== SAVE THE DEPLOYMENTS YOU WANT AS deployments-live OR deployments-intermission ====----\r\n8x --- SNIP Copy from below here SNIP --- x8\r\n\r\n--#############################################################################\r\n-- deployment(id, weapName, numUnits, facility, fallback, description)\r\n--  ID is between 1 and 6 characters long, alpha-numeric ONLY (a-z, A-Z, 0-9)\r\n--  weapname is either the Weapon Spec { Country, Category, Class, Type}\r\n--   or the th_blitz name, e.g. de-rifle\r\n--  numUnits is the number of these vehicles to deploy\r\n--  facility is either the name or facility ID of the initial facility\r\n--  fallback is either the name or facility ID of the fallback facility\r\n--  description is the name given to the unit in-game\r\n--#############################################################################\r\n\r\ndeployment(\'frbg01\',    \'db7\',          15,     \'Courcy Airfield\',    \'Abbeville Airfield\',   \'French Bomber Group Number 1\')\r\n\r\ndeployment(\'frbg02\',    \'db7\',          15,     \'Abbeville Airfield\', \'Marck Airfield\',   \'French Bomber Group Number 2\')\r\n\r\ndeployment(\'frbg03\',    {3,1,1,2},      15,     \'Wizernes Airfield\',  \'Marck Airfield\',   \'French Bomber Group Number 3\')\r\n\r\n                                                -- Marck Airfield / Marck Airfield\r\ndeployment(\'frbg04\',    {3,1,1,2},      15,     3532,   3532,   \'French Bomber Group Number 4\')\r\n\r\n                                                -- &#65533;taples Airfield / Manston Airfield\r\ndeployment(\'ukbg01\',    {1,1,1,3},      15,     3675,   3723,   \'British Bomber Group Number 1\')\r\n\r\n                                                -- Vitry-En-Artois Airfield / &#65533;taples Airfield\r\ndeployment(\'ukbg02\',    {1,1,1,3},      15,     3137,   3675,   \'British Bomber Group Number 2\')\r\n\r\