Buzancy\" },\r\n	 { \"2ab\", \"Hastiere\" },\r\n	 { \"2id\", \"Philipville\" },\r\n	 { \"3pzd\", \"Spontin\" },\r\n	 { \"3pdkg1\", \"Anhee\" },\r\n	 { \"3pdkg2\", \"Dinant\" },\r\n	 { \"33id\", \"Spincourt\" },\r\n	 { \"33idkg1\", \"Etain\" },\r\n	 { \"33idkg2\", \"Fresnes\" },\r\n	 { \"37ds\", \"Terneuzen\" },\r\n	 { \"38ds\", \"Namur\" },\r\n	 { \"3ib\", \"Profondeville\" },\r\n	 { \"4pzd\", \"Montmedy\" },\r\n	 { \"4zf\", \"Gravenpolder\" },\r\n	 { \"4pdkg1\", \"Stenay\" },\r\n	 { \"4pdkg2\", \"Dun\" },\r\n	 { \"43ir\", \"Vireaux\" },\r\n	 { \"4blm\", \"Clermont-en-Argonne\" },\r\n	 { \"4thmacrd\", \"Chilly\" },\r\n	 { \"4ib\", \"Flavion\" },\r\n	 { \"5zf\", \"Vlissingen\" },\r\n	 { \"52w\", \"Antwerp\" },\r\n	 { \"5dina\", \"Montfaucon\" },\r\n	 { \"5ib\", \"Hastiere\" },\r\n	 { \"6zf\", \"Dun\" },\r\n	 { \"60fw\", \"Knokke\" },\r\n	 { \"60w\", \"Brussels\" },\r\n	 { \"605rp\", \"Charleville\" },\r\n	 { \"61w\", \"Maubeuge\" },\r\n	 { \"70bw\", \"Maubeuge\" },\r\n	 { \"70w\", \"Maubeuge\" },\r\n	 { \"75w\", \"Brussels\" },\r\n	 { \"76w\", \"Brussels\" },\r\n	 { \"8zf\", \"Sedan\" },\r\n	 { \"8dc\", \"Montfaucon\" },\r\n	 { \"fpc\", \"Breskens\" },\r\n	 { \"fda\", \"Verdun\" },\r\n	 { \"gb18\", \"Montfaucon\" },\r\n	 { \"gb19\", \"Reims\" },\r\n	 { \"gbi12\", \"Montfaucon\" },\r\n	 { \"gbiii12\", \"Reims\" },\r\n	 { \"gci1\", \"Abbeville\" },\r\n	 { \"gciii3\", \"Montfaucon\" },\r\n	 { \"gb6\", \"Reims\" },\r\n	 { \"gc21\", \"St.Omer\" },\r\n	 { \"2jg1g\", \"Etain\" },\r\n	 { \"26k1g\", \"Mendig\" },\r\n	 { \"3jg1g\", \"Metz\" },\r\n	 { \"53k1g\", \"Vlissingen\" },\r\n	 { \"26k1st\", \"Etain\" },\r\n	 { \"53k1st\", \"Metz\" },\r\n	 { \"2jg2g\", \"Aachen\" },\r\n	 { \"26k2g\", \"Hahn\" },\r\n	 { \"3jg2g\", \"Köln\" },\r\n	 { \"53k2g\", \"Aachen\" },\r\n	 { \"26k2st\", \"Etain\" },\r\n	 { \"53k2st\", \"Metz\" },\r\n	 { \"jg2\", \"Hahn\" },\r\n	 { \"jg3\", \"Mendig\" },\r\n	 { \"26kgs\", \"Aachen\" },\r\n	 { \"53kgs\", \"Mendig\" },\r\n	 { \"sas\", \"Eghezee\" },\r\n	}\r\n}\r\n\r\nfunction resupplyTime (weapon, facility)\r\n  local interval = wwii_config.resupplyTime\r\n  if weapon.wCategory == _GROUND_VEHICLE then\r\n    if weapon.wClass == 4 then\r\n      return interval * 2.0\r\n    end\r\n  end\r\n  return interval\r\nend\r\n\r\nfunction maxCaptureObjectives (population)\r\n	-- If population is not specified, use the current chat population\r\n	if population == nil then population = getPopulation() end\r\n\r\n	local minimum, maximum = 4, 20\r\n	local populationPer = 60\r\n	local target = math.floor(population / populationPer)\r\n\r\n	if target > maximum then return maximum end\r\n	if target < minimum then return minimum end\r\n\r\n	-- Otherwise what we have is good\r\n	return target\r\nend\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n', '2006-11-08 02:22:33'),
