('intermission-divisionalgroupings', 'intermission = {\r\n	title = \"Default Divisional Start\",\r\n\r\n	-- If you want the brigades to be locked in place after deployment\r\n	-- specify the initial movement delay duration here\r\n	-- Time is in seconds\r\n	brigadeInitialMovementTime = { days = 0, hours = 1, minutes = 0, seconds = 0 },\r\n\r\n	-- If you want to specify custom \"rare spawn\" deployments,\r\n	-- add a weaponDeployment line in the deployments section\r\n	unitDeployments = {\r\n	-- { id = \"depz01\", weapon = \"pzvie\", facility = \"Antwerp South Armybase\", fallback = \"Brussels South \r\n\r\nArmybase\", description = \"Panzer Division\" },\r\n	},\r\n\r\n	-- CP Ownerships\r\n	-- By default all CPs are reset to their original ownership,\r\n	-- to change this behavior specify one of:\r\n	--  default = \"none\" -- leaves the map alone\r\n	--  default = WWII_ENGLAND|WWII_FRANCE|WWII_GERMANY|WWII_CHINA\r\n	ownerships = {\r\n	 default = \"WWII_ENGLAND|WWII_FRANCE|WWII_GERMANY|WWII_CHINA\",\r\n	 uk = {\r\n		\"Aarschot\",\r\n		\"Tienen\",\r\n		\"Jodoigne\",\r\n		\"Eghezee\",\r\n		\"Andenne\",\r\n		\"Bergen Op Zoom\",\r\n		\"Roosendaal\",\r\n		\"Wuustwezel\",\r\n		\"Oostmalle\",\r\n		\"Grobbendonk\",\r\n	 },\r\n	 france = {\r\n	 },\r\n	 germany = {\r\n		\"Veere\",\r\n		\"Westkapelle\",\r\n		\"Vlissingen\",\r\n	 },\r\n	 china = {\r\n	 },\r\n	},\r\n\r\n	-- Brigade deployments\r\n	-- { \"shortname\", \"cp name\" }\r\n	-- Special case: cp name can be \"offmap\"\r\n	brigades = {\r\n	 { \"1agd\", \"Vlissingen\" },\r\n	 { \"8zf\", \"Gravenpolder\" },\r\n	 { \"5zf\", \"Krabbendijke\" },\r\n	 { \"2agd\", \"Hellevoetsluis\" },\r\n	 { \"4zf\", \"Huy\" },\r\n	 { \"6zf\", \"Kamperland\" },\r\n	 { \"jg2\", \"Gilze\" },\r\n	 { \"2jg1g\", \"Vlissingen\" },\r\n	 { \"2jg2g\", \"Aachen\" },\r\n	 { \"jg3\", \"Wiltz\" },\r\n	 { \"3jg1g\", \"Verviers\" },\r\n	 { \"3jg2g\", \"Bertrix\" },\r\n	 { \"53kgs\", \"Gilze\" },\r\n	 { \"53k1st\", \"Aachen\" },\r\n	 { \"53k2st\", \"Vlissingen\