	 { \"gbi12\", \"Ramsgate\" },\r\n	 { \"gb18\", \"Ramsgate\" },\r\n	 { \"gb19\", \"Folkestone\" },\r\n	 { \"gbiii12\", \"Lympne\" },\r\n          { \"1dim\", \"Boulogne\" },\r\n          { \"1ir\", \"Escoeuilles\" },\r\n          { \"43ir\", \"Samer\" },\r\n          { \"14c\", \"Escoeuilles\" },\r\n	 { \"2dina\", \"Calais\" },\r\n	 { \"110ir\", \"Ardres\" },\r\n	 { \"13dp\", \"Ardres\" },\r\n	 { \"22dp\", \"Gravelines\" },\r\n          { \"4thmacrd\", \"Le Crotoy\" },\r\n          { \"104atr\", \"Le Crotoy\" },\r\n          { \"605rp\", \"Le Crotoy\" },\r\n          { \"101er\", \"Fressenneville\" },\r\n	 { \"2ndlmd\", \"Le Treport\" },\r\n	 { \"4blm\", \"Le Treport\" },\r\n	 { \"8dc\", \"Cayeux\" },\r\n	 { \"13rd\", \"Fressenneville\" },\r\n          { \"12dim\", \"Berck-Plage\" },\r\n          { \"1bdm\", \"Le Touquet\" },\r\n          { \"13edble\", \"Berck-Plage\" },\r\n          { \"106rim\", \"Le Touquet\" },\r\n	 { \"5dina\", \"Le Touquet\" },\r\n	 { \"14dp\", \"Montreuil\" },\r\n	 { \"27ir\", \"Montreuil\" },\r\n	 { \"6dp\", \"Samer\" },\r\n          { \"1dia\", \"Ramsgate\" },\r\n          { \"601gia\", \"Calais\" },\r\n          { \"602gia\", \"Le Touquet\" },\r\n	 { \"19df\", \"Calais\" },\r\n	 { \"37ds\", \"Oostende\" },\r\n	 { \"38ds\", \"Dunkerque\" },\r\n          { \"1id\", \"Oostende\" },\r\n          { \"sas\", \"Zeebrugge\" },\r\n          { \"1gb\", \"Oostende\" },\r\n          { \"3ib\", \"Jabbeke\" },\r\n	 { \"2id\", \"Dunkerque\" },\r\n	 { \"2ab\", \"Dunkerque\" },\r\n	 { \"4ib\", \"Veurne\" },\r\n  	 { \"5ib\", \"Gravelines\" }, \r\n          { \"3id\", \"Oostende\" },\r\n	 { \"33ab\", \"Veurne\" },\r\n	 { \"8ib\", \"Zeebrugge\" },\r\n  	 { \"9ib\", \"Diksmuide\" },    \r\n          { \"60fw\", \"Ramsgate\" },\r\n          { \"60w\", \"Lympne\" },\r\n          { \"61w\", \"Ramsgate\" },\r\n	 { \"70bw\", \"Folkestone\" },\r\n	 { \"75w\", \"Le Touquet\" },\r\n	 { \"76w\", \"Folkestone\" },\r\n	 { \"70w\", \"Le Touquet\" },\r\n	 { \"52w\", \"Calais\" },\r\n          { \"1abd\", \"Folkestone\" },\r\n          { \"1pb\", \"Calais\" },\r\n          { \"2pb\", \"Le Touquet\" },\r\n	 },\r\n}\r\n---- Enable the \"INTEL\" system telling players where to fight?\r\n---- Recommended: false (for campaigns)\r\newsCheckEnabled = false\r\n\r\n---- Interval between EWS checks\r\n---- Recommended: timeInSeconds({ minutes = 15 })\r\newsCheckInterval = timeInSeconds({ minutes = 20 })\r\n\r\n-- Automatic attack objective controls\r\n\r\n-- true/false - should automatic attack objective placement be enabled\r\ngameAOPlacementEnabled = true\r\n-- How long should we wait after AOs become spare before notifying the HCs\r\ngameAONoticeDelay = timeInSeconds({ minutes = 3 })\r\n-- How long should we wait after notifying the HCs before placing an AO\r\ngameAOPlaceTime = timeInSeconds({ minutes = 2 })\r\n-- What fraction of available AOs must be placed?\r\ngameAOMinimumRatio = 0.5\r\n\r\n----------------------------------------------------------------------\r\n-- maxCaptureObjectives()\r\n--	Return the current maximum allowed capture objectives\r\n----------------------------------------------------------------------\r\n\r\nfunction maxCaptureObjectives (population)\r\n	-- If population is not specified, use the current chat population\r\n	if population == nil then population = getPopulation() end\r\n\r\n	local minimum, maximum = 3, 20\r\n	local populationPer = 55\r\n	local target = math.floor(population / populationPer)\r\n\r\n	if target > maximum then return maximum end\r\n	if target < minimum then return minimum end\r\n\r\n	-- Otherwise what we have is good\r\n	return target\r\nend\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n', '2010-05-25 15:57:31');
