('live:save-map1', '-- Save the current map state.\r\n\r\nfunction saveMapStateToFile(filename)\r\n  local output = \"\"\r\n  for cp in allCityCPs() do\r\n\r\n   -- Save CP states\r\n   output = output .. \'setCP(\"\'..cp.name..\'\", \'..cp.country..\")\\n\"\r\n\r\n   -- Save all the firebase states\r\n   for link in allLinksFrom(cp) do\r\n    linkback = link.endDepot.m_outgoingLink\r\n    if link and link.firebase and linkback and linkback.firebase then\r\n     local fb = nil\r\n     if link.firebase:isOpen() then fb = linkback.firebase\r\n     elseif linkback.firebase:isOpen() then fb = link.firebase end\r\n     if fb ~= nil then output = output .. \"blowFirebase(\" .. fb.uOID .. \")\\n\"\r\n     end\r\n    end\r\n   end\r\n\r\n  end\r\n\r\n  -- Save brigade deployments\r\n  local cpName\r\n  for unit in allStratHCUnits() do\r\n   if unit:homeCP() then cpName = unit:homeCP().name else cpName = \'offmap\' end\r\n   output = output .. \'deploy(\"\'..unit:callsign()..\'\", \"\'..cpName..\'\", \'..unit:nextMoveIn()..\')\' .. \"\\n\"\r\n  end\r\n\r\n  if filename then\r\n    output = output .. \"print(\'Map state restored\')\\n\"\r\n    local f = assert(io.open(filename, \"w\"))\r\n    f:write(output)\r\n    f:close()\r\n  else\r\n    print(output)\r\n  end\r\nend\r\n\r\nfunction autosaveMapState(filename)\r\n if wwii_config.arena.lock > 0 then return end\r\n print(\"Saving map state to \" .. filename)\r\n saveMapStateToFile(filename)\r\nend\r\n\r\nlocal mapfilename = \"map-state\"\r\nlocal mapfile = \"/playnet/lua/\"..mapfilename..\".lua\"\r\n\r\nfunction loadMapState(filename)\r\n    output = output .. \"print(\'Map state restored\')\\n\"\r\n    print(output)\r\n require \'map-state\'\r\nend\r\n\r\n', '2013-07-30 23:44:54'),
('save-map1', '-- Save the current map state.\r\n\r\nfunction saveMapStateToFile(filename)\r\n  local output = \"\"\r\n  for cp in allCityCPs() do\r\n\r\n   -- Save CP states\r\n   output = output .. \'setCP(\"\'..cp.name..\'\", \'..cp.country..\")\\n\"\r\n\r\n   -- Save all the firebase states\r\n   for link in allLinksFrom(cp) do\r\n    linkback = link.endDepot.m_outgoingLink\r\n    if link and link.firebase and linkback and linkback.firebase then\r\n     local fb = nil\r\n     if link.firebase:isOpen() then fb = linkback.firebase\r\n     elseif linkback.firebase:isOpen() then fb = link.firebase end\r\n     if fb ~= nil then output = output .. \"blowFirebase(\" .. fb.uOID .. \")\\n\"\r\n     end\r\n    end\r\n   end\r\n\r\n  end\r\n\r\n  -- Save brigade deployments\r\n  local cpName\r\n  for unit in allStratHCUnits() do\r\n   if unit:homeCP() then cpName = unit:homeCP().name else cpName = \'offmap\' end\r\n   output = output .. \'deploy(\"\'..unit:callsign()..\'\", \"\'..cpName..\'\", \'..unit:nextMoveIn()..\')\' .. \"\\n\"\r\n  end\r\n\r\n  if filename then\r\n    output = output .. \"print(\'Map state restored\')\\n\"\r\n    local f = assert(io.open(filename, \"w\"))\r\n    f:write(output)\r\n    f:close()\r\n  else\r\n    print(output)\r\n  end\r\nend\r\n\r\nfunction autosaveMapState(filename)\r\n if wwii_config.arena.lock > 0 then return end\r\n print(\"Saving map state to \" .. filename)\r\n saveMapStateToFile(filename)\r\nend\r\n\r\nlocal mapfilename = \"map-state\"\r\nlocal mapfile = \"/playnet/lua/\"..mapfilename..\".lua\"\r\n\r\nfunction loadMapState(filename)\r\n    output = output .. \"print(\'Map state restored\')\\n\"\r\n    print(output)\r\n require \'map-state\'\r\nend\r\n\r\n\r\n\r\n', '2013-07-30 23:45:54'),
('stackedstart', 'intermission = {Stacked Together}\r\n	title = \"Default Divisional Start\",\r\n\r\n	-- If you want the brigades to be locked in place after deployment\r\n	-- specify the initial movement delay duration here\r\n	-- Time is in seconds\r\n	brigadeInitialMovementTime = { days = 0, hours = 1, minutes = 0, seconds = 0 },\r\n\r\n	-- CP Ownerships\r\n	-- By default all CPs are reset to their original ownership,\r\n	-- to change this behavior specify one of:\r\n	--  default = \"none\" -- leaves the map alone\r\n	--  default = WWII_ENGLAND|WWII_FRANCE|WWII_GERMANY|WWII_CHINA\r\n	ownerships = {\r\n	 default = \"none\",\r\n	 uk = {\r\n		\"Aarschot\",\r\n		\"Tienen\",\r\n		\"Jodoigne\",\r\n		\"Eghezee\",\r\n		\"Andenne\",\r\n		\"Bergen Op Zoom\",\r\n		\"Roosendaal\",\r\n		\"Wuustwezel\",\r\n		\"Oostmalle\",\r\n		\"Grobbendonk\",\r\n	 },\r\n	 france = {\r\n	 },\r\n	 germany = {\r\n		\"Veere\",\r\n		\"Westkapelle\",\r\n		\"Vlissingen\",\r\n	 },\r\n	 china = {\r\n	 },\r\n	 },\r\n\r\n	-- Brigade deployments\r\n	-- { \"shortname\", \"cp name\" }\r\n	-- Special case: cp name can be \"offmap\"\r\n	brigades = {\r\n	 { \"1agd\", \"Vlissingen\" },\r\n	 { \"8zf\", \"Gravenpolder\" },\r\n	 { \"5zf\", \"Krabbendijke\" },\r\n	 { \"2agd\", \"Hellevoetsluis\" },\r\n	 { \"4zf\", \"Huy\" },\r\n	 { \"6zf\", \"Kamperland\" },\r\n	 { \"jg2\", \"Gilze\" },\r\n	 { \"2jg1g\", \"Vlissingen\" },\r\n	 { \"2jg2g\", \"Aachen\" },\r\n	 { \"jg3\", \"Wiltz\" },\r\n	 { \"3jg1g\", \"Verviers\" },\r\n	 { \"3jg2g\", \"Bertrix\" },\r\n	 { \"53kgs\", \"Gilze\" },\r\n	 { \"53k1st\", \"Aachen\" },\r\n	 { \"53k2st\", \"Vlissingen\" },\r\n	 { \"53k1g\", \"Verviers\" },\r\n	 { \"53k2g\", \"Vlissingen\" },\r\n	 { \"26kgs\", \"Aachen\" },\r\n	 { \"26k1st\", \"Verviers\" },\r\n	 { \"26k2st\", \"Bertrix\" },\r\n	 { \"26k1g\", \"Vlissingen\" },\r\n	 { \"26k2g\", \"Verviers\" },\r\n	 { \"16id\", \"Spontin\" },\r\n	 { \"16idkg1\", \"Spontin\" },\r\n	 { \"16idkg2\", \"Spontin\" },\r\n     { \"16idkg3\", \"Spont